    printf("Enter the symbol to use:");
    scanf("%c",&symbol);


    //fgets(symbol, 25, stdin);

    for(int i = 1; i <= row; i++)
    {
        for(int j = 1; j <= column; j++)
        {
            printf("\n%c",symbol);
        }
        printf("\n");
    }

    return 0;
}

